static int observer_control(void){void* source=NULL;void* destination=NULL;root roots[2]={0};const int32_t values[4]={8,1,8,-1};const struct ube_value_field field={0,&long_layout};const size_t root_offset=0;const struct ube_value_layout array_layout={sizeof(void*),1,1,&field,1,&root_offset};CHECK(ube_gc_root_enter(&roots[0],&source)&&ube_gc_root_enter(&roots[1],&destination)&&ube_value_try_resize(&source,4,&long_layout,0));memcpy(ube_array_element(source,0),values,sizeof values);ube_err_set(77,"previous","byte key copy control");observation_start(0);CHECK(byte_key_assign(&destination,&source,&array_layout));observation_stop();CHECK(destination!=source&&ube_value_array_length(&destination)==4&&memcmp(values,ube_array_element(destination,0),sizeof values)==0&&memcmp(values,ube_array_element(source,0),sizeof values)==0&&ube_err_number()==77&&observed.publication==16&&observed.other==0&&observed.byte_copied==0&&observed.heap_events==1&&observed.gc_peak==observed.gc_before+16+storage_array_header());CHECK(ube_gc_root_leave(&roots[1])&&ube_gc_root_leave(&roots[0]));(void)ube_gc_collect();CHECK(ube_gc_live_allocation_bytes()==0&&storage_root_count()==0);printf("{\"suite\":\"observer-control\",\"actualCopiedLongPayload\":16,\"heapCallbacks\":1,\"passed\":true}\n");return 0;}
