int main(int argc,char** argv){if(argc==3&&strcmp(argv[1],"--suite")==0){int status=2;if(strcmp(argv[2],"fixtures")==0)status=scaling();if(strcmp(argv[2],"domains")==0)status=budgets_domains();if(strcmp(argv[2],"faults")==0)status=allocation_faults();if(strcmp(argv[2],"roots")==0)status=roots();if(strcmp(argv[2],"observer-control")==0)status=observer_control();if(status)return status;}else if(argc==1){CHECK(small_oracle()==0&&scaling()==0&&budgets_domains()==0&&allocation_faults()==0&&roots()==0&&observer_control()==0);}else return 2;printf("PASS byte key native assertions:%u\n",assertions);return 0;}
